import React, { useEffect, useState } from "react";
import ReactStars from "react-rating-stars-component";
import { Swiper, SwiperSlide } from "swiper/react";
import "swiper/css";
import "swiper/css/free-mode";
import "swiper/css/pagination";
import "../../App.css";
import { FaStar } from "react-icons/fa";
import { Autoplay, FreeMode, Pagination } from "swiper/modules";
import { apiConnector } from "../../services/apiconnector";
import { ratingsEndpoints } from "../../services/api";

function ReviewSlider() {
  const [reviews, setReviews] = useState([]);  // Ensuring it's an array
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchReviews = async () => {
      try {
        const { data } = await apiConnector("GET", ratingsEndpoints.REVIEWS_DETAILS);

        console.log("Fetched Reviews: ", data);

        // Ensure data.reviews is an array before setting state
        if (data && Array.isArray(data.reviews)) {
          setReviews(data.reviews);
        } else {
          console.error("Unexpected API response format:", data);
          setReviews([]); // Set to empty array if response is incorrect
        }
      } catch (err) {
        console.error("Error fetching reviews:", err);
        setError("Failed to load reviews.");
      } finally {
        setLoading(false);
      }
    };

    fetchReviews();
  }, []);

  if (loading) return <p>Loading reviews...</p>;
  if (error) return <p>{error}</p>;

  return (
    <div className="review-slider-container">
      <h2 className="section_heading text-center">What Our Users Say</h2>

      <Swiper
        slidesPerView={1}
        spaceBetween={30}
        freeMode={true}
        pagination={{ clickable: true }}
        autoplay={{ delay: 3000, disableOnInteraction: false }}
        modules={[Autoplay, FreeMode, Pagination]}
        className="swiper"
      >
        {reviews.length > 0 ? (
          reviews.map((review, index) => (
            <SwiperSlide key={index} className="swiper-slide p-4 bg-gray-800 rounded-lg">
              <div className="flex items-center mb-3">
                <FaStar className="text-yellow-500" />
                <h3 className="ml-2 text-lg font-semibold text-white">{review.name}</h3>
              </div>
              <p className="text-sm text-gray-400">
                {review.comment?.length > 100
                  ? review.comment.substring(0, 100) + "..."
                  : review.comment || "No comment provided."}
              </p>
              <ReactStars
                count={5}
                value={review.rating || 0}
                size={24}
                activeColor="#ffd700"
                edit={false}
              />
            </SwiperSlide>
          ))
        ) : (
          <p className="text-center text-gray-400">No reviews available.</p>
        )}
      </Swiper>
    </div>
  );
}

export default ReviewSlider;
